class FakeRepository {
    int calls;
    String find(int id) { calls++; return "Готово"; }
}
class Service {
    private final FakeRepository repository;
    Service(FakeRepository repository) { this.repository = repository; }
    String load(int id) { return repository.find(id); }
}
public class Main {
    public static void main(String[] args) {
        FakeRepository fake = new FakeRepository();
        String actual = new Service(fake).load(4);
        if (!actual.equals("Готово")) throw new AssertionError("ответ");
        System.out.println(fake.calls);
    }
}

